def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # Remove expired entries (not strictly necessary but keeps cache clean)
            keys_to_delete = [k for k, (v, wt) in cache.items() if wt + ttl <= t]
            for k in keys_to_delete:
                del cache[k]

            # If key exists, remove it to re-add it as most recently used
            if key in cache:
                del cache[key]
            # If cache is full, evict least recently used
            elif len(cache) >= capacity:
                cache.popitem(last=False)  # Remove first (least recently used)

            # Add the new entry
            cache[key] = (value, t)
            # Move to end to mark as most recently used
            cache.move_to_end(key)

        elif op[0] == 'get':
            _, t, key = op
            # Check if key exists and has not expired
            if key in cache:
                value, write_time = cache[key]
                if write_time + ttl > t:
                    # Entry is still valid
                    results.append(value)
                    # Mark as most recently used
                    cache.move_to_end(key)
                else:
                    # Entry has expired
                    del cache[key]
                    results.append(-1)
            else:
                # Key not in cache
                results.append(-1)

    return results

